namespace Acme.Orders;

public class Mail(string to, string subject)
{
    public string To { get; } = to;
    public string Subject { get; } = subject;
}

public interface IMailer
{
    Task SendAsync(Mail mail, CancellationToken ct);
}

using Acme.Orders;
using Moq;
using Xunit;

namespace Acme.Orders.Tests;

public class OrderServiceTests
{
    [Fact]
    public async Task PlaceAsync_SendsConfirmation()
    {
        var mailer = new Mock<IMailer>();
        mailer
            .Setup(m => m.SendAsync(It.IsAny<Mail>(), It.IsAny<CancellationToken>()))
            .Returns(Task.CompletedTask);
        var service = new OrderService(mailer.Object);

        await service.PlaceAsync(new Order(42, "a@example.com"), CancellationToken.None);
    }
}

